import subprocess
result = subprocess.run(['pdftotext', '-layout', 'main.pdf', '-'], capture_output=True, text=True)
pages = result.stdout.split('\f')
# Search for Limitations, References, Ethics in each page
for i, page in enumerate(pages):
    for keyword in ['Limitations', 'Ethical Considerations', 'Ethics Statement', 'References']:
        lines = page.split('\n')
        for line in lines:
            stripped = line.strip()
            # Check if it's a section header (starts with number or is standalone)
            if stripped and keyword in stripped and len(stripped) < 60:
                if any(c.isdigit() for c in stripped[:5]) or stripped.startswith(keyword):
                    print(f'Page {i+1}: {stripped}')
                    break
